import { Feed, Button, type Post } from "march/ui"

// üç dizelik şiirler akışı: her gönderi kendi kartıyla çizilir (renderPost); "Yeni şiir" yukarıda bekleyen
// gönderi hapını gösterir, hapa basınca şiirler akışın başına katılır
const LINES = [
  ["Sabah sisinde", "martı tek başına", "denizi çizer"],
  ["Çay buğusunda", "eski bir şarkı döner", "pencere açık"],
  ["Kedi uykuda", "güneş halıya düşmüş", "saat durmuş sanki"],
  ["Yağmur damlası", "kaldırımda bir harita", "eve dönüş yolu"],
]
let n = 0
const poem = (): Post => { const l = LINES[n % LINES.length]!; n++; return { id: `h${n}`, author: { name: "Şiir Defteri" }, time: Date.now(), text: l.join("\n"), likes: 0 } }

export function HaikuFeed() {
  let $posts: Post[] = [poem(), poem()]
  let $waiting: Post[] = []
  return <div sx={{ flex: "col", gap: 2 }}>
    <Button size="sm" variant="ghost" on:click={() => $waiting = [poem(), ...$waiting]}>Yeni şiir</Button>
    <Feed posts={$posts} newCount={$waiting.length} newColor="brand-purple" end={<i>Defterin sonu ✒️</i>}
      labels={{ newPosts: (c) => `${c} yeni şiir` }}
      onShowNew={() => { $posts = [...$waiting, ...$posts]; $waiting = [] }}
      renderPost={(p) => <blockquote sx={{ p: 3, text: ["lg", "center"] }}>{p().text?.split("\n").map((line) => <div>{line}</div>)}</blockquote>} />
  </div>
}

import { Feed, toast, type Post } from "march/ui"

// bir topluluk akışı: ilk sayfa ağdan gelir (iskelet kartlar), sona kaydırınca sonraki sayfa, aşağı çekince yenileme;
// beğeniler iyimser güncellenir. Ağ yerine bir bekleme kullanılır
const PHOTO = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42mPY/f2C0tE4BrFUE5FgXQAtngULJa1nqAAAAABJRU5ErkJggg=="
const CLUBS = ["HADİ Koşu Kulübü", "Pazar Bisiklet Grubu", "Fotoğraf Atölyesi", "Kitap Kulübü"]
const TEXTS = ["Yeni rota denendi: orman yolu 8 km.", "Akşam turu yağmur yüzünden yarına kaldı.", "Atölyede analog banyo günü!", "Ayın kitabı belli oldu."]
const wait = (ms: number) => new Promise((r) => setTimeout(r, ms))
const page = (from: number): Post[] => Array.from({ length: 4 }, (_, i) => {
  const k = from + i
  return { id: `c${k}`, author: { name: CLUBS[k % 4]! }, time: Date.now() - k * 40 * 60_000, text: TEXTS[k % 4], likes: 10 + k * 7, comments: k % 5,
    media: k % 3 === 0 ? [{ src: PHOTO, alt: "Orman" }] : undefined }
})

export function CommunityFeed() {
  let $posts: Post[] = []
  let $loading = true
  let $pages = 1
  void wait(800).then(() => { $posts = page(0); $loading = false })
  return <div sx={{ flex: "col", gap: 2 }}>
    <Feed posts={$posts} loading={$loading} hasMore={$pages < 3} label="Topluluk akışı"
      onRefresh={() => wait(600).then(() => { $posts = page(0); $pages = 1; toast("Akış yenilendi") })}
      onLoadMore={() => wait(600).then(() => { $posts = [...$posts, ...page($posts.length)]; $pages++ })}
      onLike={(on, p) => { $posts = $posts.map((x) => (x.id === p.id ? { ...x, liked: on, likes: x.likes + (on ? 1 : -1) } : x)) }}
      onComment={(p) => toast(`${p.author.name}: yorumlar`)} />
  </div>
}

import { Feed, Button, Badge, type Post } from "march/ui"
import { star } from "march/icons"

// Feed'in bütün özellikleri: gönderiler, ilk yükleme (iskelet sayısı), sonraki sayfa ve yenileme, bekleyen yeni
// gönderiler (hap: kendi içeriği ve rengi), görünüm, boş akış içeriği, erişilebilir ad, kendi metinler, bitiş işareti,
// hareket, sınıf ve her PostCard'a giden olaylar ve özellikler (onLike, onComment, onShare, onOpenMedia, onAuthor,
// menu, clamp, postProps); renderPost üstteki küçük akışta
let seq = 0
const make = (k: number): Post[] => Array.from({ length: k }, () => {
  const i = ++seq
  return { id: `l${i}`, author: { name: `Üye ${i}` }, time: Date.now() - i * 60_000, likes: i, comments: i % 3, shares: 0,
    text: `Gönderi ${i}: bugün kulüpte uzun bir gün geçti, akşam herkes bahçede buluştu ve yeni dönemin planları konuşuldu.` }
})

export function FeedLab() {
  let $posts: Post[] = make(2)
  let $loading = false
  let $more = true
  let $waiting: Post[] = []
  let $flat = false
  let $log = "-"
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button size="sm" variant="ghost" on:click={() => $waiting = [...make(1), ...$waiting]}>Yeni gelsin</Button>
      <Button size="sm" variant="ghost" on:click={() => { $posts = []; $more = false }}>Boşalt</Button>
      <Button size="sm" variant="ghost" on:click={() => $loading = !$loading}>{$loading ? "Yüklendi" : "Yükleniyor"}</Button>
      <Button size="sm" variant="ghost" on:click={() => $flat = !$flat}>{$flat ? "Kartlar" : "Düz"}</Button>
      <Badge tone="primary">{$log}</Badge>
    </div>
    {/* üstte: sanal liste yalnız ekrana yakın olanı çizer */}
    <Feed posts={[{ id: "own", author: { name: "Duyuru" }, time: Date.now(), text: "Kendi çizimin: renderPost", likes: 0 }]} end={false} newPill={false}
      renderPost={(p) => <p sx={{ p: 2, text: "bold", color: "brand-orange" }}>{p().text}</p>} />
    <Feed class="lab-feed" label="Laboratuvar akışı" posts={() => $posts} loading={() => $loading} skeletons={2} hasMore={() => $more}
      onRefresh={() => { $posts = make(2); $log = "yenilendi" }}
      onLoadMore={() => { $posts = [...$posts, ...make(2)]; $more = $posts.length < 6 }}
      newCount={() => $waiting.length} onShowNew={() => { $posts = [...$waiting, ...$posts]; $waiting = []; $log = "yeniler eklendi" }}
      newPill={(c) => `⬆ ${c} taze gönderi`} newColor="brand-green" motion={false} variant={() => ($flat ? "flat" : "card")}
      empty={<p sx={{ text: "center", color: "muted" }}>Burada henüz kimse yazmadı 🌱</p>}
      labels={{ loading: "Akış yükleniyor", loadingMore: "Daha fazlası geliyor", empty: "Boş", end: "Hepsi bu kadar" }}
      end={<b>— son —</b>} clamp={1}
      onLike={(on, p) => { $posts = $posts.map((x) => (x.id === p.id ? { ...x, liked: on, likes: x.likes + (on ? 1 : -1) } : x)); $log = `beğeni: ${p.author.name}` }}
      onComment={(p) => $log = `yorum: ${p.author.name}`} onShare={(p) => $log = `paylaş: ${p.author.name}`}
      onOpenMedia={(i) => $log = `fotoğraf ${i + 1}`} onAuthor={(p) => $log = `yazar: ${p.author.name}`}
      menu={[{ label: "Kaydet", icon: star, onSelect: (p: Post) => $log = `kaydedildi: ${p.id}` }]}
      postProps={{ avatar: false, likeColor: "brand-green", labels: { like: "Beğen" } }} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { FeedLab } from "./FeedLab.tsx"

// FeedLab'in testleri: kaydedince Testler sekmesinde çalışır. Akış sanal bir liste: yalnız ekrana yakın gönderileri
// çizer; gönderi arayan testler görünmez ama ekranda duran bir kutuda çizilir
const onScreen = () => {
  const box = document.body.appendChild(document.createElement("div"))
  box.style.cssText = "position:fixed;inset:0 auto auto 0;inline-size:600px;opacity:0;pointer-events:none"
  return { container: box, root: box }
}
test("bekleyen gönderi hapı kendi içeriğiyle görünür; basınca gönderiler akışa katılır", async () => {
  const s = renderTest(() => <FeedLab />)
  await s.click("Yeni gelsin")
  expect(s.sees("⬆ 1 taze gönderi")).toBe(true)
  await s.click("⬆ 1 taze gönderi")
  await s.wait(() => s.sees("yeniler eklendi"))
  expect(s.sees("yeniler eklendi")).toBe(true)
})

test("akış boşalınca empty içeriği görünür", async () => {
  const s = renderTest(() => <FeedLab />)
  await s.click("Boşalt")
  expect(s.sees("Burada henüz kimse yazmadı")).toBe(true)
})

test("postProps her gönderiye gider: Beğen düğmesi onLike'ı çalıştırır", async () => {
  const s = renderTest(() => <FeedLab />, onScreen())
  await s.wait(() => s.find("Beğen"))   // gönderiler kare kare çizilir
  await s.click("Beğen")
  await s.wait(() => s.sees("beğeni: Üye"))
  expect(s.sees("beğeni: Üye")).toBe(true)
})

test("renderPost ile çizilen gönderi PostCard değil, kendi içeriği", async () => {
  const s = renderTest(() => <FeedLab />, onScreen())
  await s.wait(() => s.sees("Kendi çizimin"))
  expect(s.sees("Kendi çizimin: renderPost")).toBe(true)
})
